INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/10learn','10learn — Learning Resources & Practice','portfolio','published','{"body": "10learn brings learning resources, saved materials, practice and class discovery into a responsive adult learning application. The documented engineering includes the public website and API, with native mobile candidates developed alongside the web experience.\n\nFree learning and class-booking workflows are distinguished from commercial features. Paid checkout, subscriptions and payouts remain unavailable; child-facing and staffed-service capabilities are not claimed as operational. Public example material is labelled rather than represented as genuine teacher or customer outcomes.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://10learn.com/"}], "category": "Educational Technology", "featured": true, "features": ["Free learning-resource and saved-library workflows", "Timed practice experiences", "Free class-booking workflow", "Responsive adult-learning website", "Documented native-client release candidates"], "description": "An adult learning website with resources, saved study materials, timed practice and free class-booking workflows.", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "Drizzle"], "project_status": "Live adult web application · native candidates", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Android/iOS candidates"], "media_ids": []}'::jsonb,'{"body": "10learn brings learning resources, saved materials, practice and class discovery into a responsive adult learning application. The documented engineering includes the public website and API, with native mobile candidates developed alongside the web experience.\n\nFree learning and class-booking workflows are distinguished from commercial features. Paid checkout, subscriptions and payouts remain unavailable; child-facing and staffed-service capabilities are not claimed as operational. Public example material is labelled rather than represented as genuine teacher or customer outcomes.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://10learn.com/"}], "category": "Educational Technology", "featured": true, "features": ["Free learning-resource and saved-library workflows", "Timed practice experiences", "Free class-booking workflow", "Responsive adult-learning website", "Documented native-client release candidates"], "description": "An adult learning website with resources, saved study materials, timed practice and free class-booking workflows.", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "Drizzle"], "project_status": "Live adult web application · native candidates", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Android/iOS candidates"], "media_ids": []}'::jsonb,'{"title": "10learn — Learning Resources & Practice | Anil Bishnoi", "description": "An adult learning website with resources, saved study materials, timed practice and free class-booking workflows.", "canonical": "https://anibish.com/portfolio/10learn"}'::jsonb,'{"title": "10learn — Learning Resources & Practice | Anil Bishnoi", "description": "An adult learning website with resources, saved study materials, timed practice and free class-booking workflows.", "canonical": "https://anibish.com/portfolio/10learn"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/bharat-mega-mall','Bharat Mega Mall — Local Commerce Discovery','portfolio','published','{"body": "Bharat Mega Mall helps buyers discover nearby shops, compare local product information and contact sellers through calls, WhatsApp or enquiries. The documented platform combines locality-aware discovery with shop storefronts, seller-managed product information and administrative moderation.\n\nThe shop remains responsible for the final sale, payment, invoice, pickup, delivery, returns and warranty. The website does not collect checkout payments. Optional delivery coordination supports shop-selected personnel without claiming an owned delivery fleet.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://bharatmm.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["Local shop and product discovery", "Locality and distance-aware search/filtering", "Shop storefronts and seller listing management", "Buyer enquiries and seller replies", "Listing moderation and optional delivery coordination"], "description": "A hyperlocal shop and product discovery marketplace that connects buyers directly with nearby sellers.", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "PostGIS"], "project_status": "Public website · discovery-led marketplace", "evidence_attested": true, "challenges": ["Connecting shared product information with shop-specific availability, locations and enquiries."], "platforms": ["Web", "Responsive buyer/seller workspaces"], "media_ids": []}'::jsonb,'{"body": "Bharat Mega Mall helps buyers discover nearby shops, compare local product information and contact sellers through calls, WhatsApp or enquiries. The documented platform combines locality-aware discovery with shop storefronts, seller-managed product information and administrative moderation.\n\nThe shop remains responsible for the final sale, payment, invoice, pickup, delivery, returns and warranty. The website does not collect checkout payments. Optional delivery coordination supports shop-selected personnel without claiming an owned delivery fleet.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://bharatmm.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["Local shop and product discovery", "Locality and distance-aware search/filtering", "Shop storefronts and seller listing management", "Buyer enquiries and seller replies", "Listing moderation and optional delivery coordination"], "description": "A hyperlocal shop and product discovery marketplace that connects buyers directly with nearby sellers.", "technologies": ["Next.js", "TypeScript", "Fastify", "PostgreSQL", "PostGIS"], "project_status": "Public website · discovery-led marketplace", "evidence_attested": true, "challenges": ["Connecting shared product information with shop-specific availability, locations and enquiries."], "platforms": ["Web", "Responsive buyer/seller workspaces"], "media_ids": []}'::jsonb,'{"title": "Bharat Mega Mall — Local Commerce Discovery | Anil Bishnoi", "description": "A hyperlocal shop and product discovery marketplace that connects buyers directly with nearby sellers.", "canonical": "https://anibish.com/portfolio/bharat-mega-mall"}'::jsonb,'{"title": "Bharat Mega Mall — Local Commerce Discovery | Anil Bishnoi", "description": "A hyperlocal shop and product discovery marketplace that connects buyers directly with nearby sellers.", "canonical": "https://anibish.com/portfolio/bharat-mega-mall"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/bishnoi-pro','Bishnoi.pro — Professional Community Foundation','portfolio','published','{"body": "Bishnoi.pro is a community-oriented professional product built around people, purpose and opportunity. The work includes the visual design library, responsive application foundations and web/API infrastructure needed to develop the broader community experience.\n\nThe public website is available. Its inspected documentation explicitly identifies the implementation as a foundation rather than a completed social-network feature set; messaging, jobs and other proposed business capabilities are not presented here as verified completed features.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://bishnoi.pro/"}], "category": "Web & SaaS Applications", "featured": false, "features": ["Dedicated desktop/mobile design library", "Responsive public application foundation", "Account, session and role foundations", "Shared interface and domain packages", "Administrative and audit foundations"], "description": "A professional community product foundation with a dedicated design library, application shell and account infrastructure.", "technologies": ["Next.js", "React", "TypeScript", "Fastify", "PostgreSQL", "Drizzle"], "project_status": "Public website · product foundation", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Mobile foundation"], "media_ids": []}'::jsonb,'{"body": "Bishnoi.pro is a community-oriented professional product built around people, purpose and opportunity. The work includes the visual design library, responsive application foundations and web/API infrastructure needed to develop the broader community experience.\n\nThe public website is available. Its inspected documentation explicitly identifies the implementation as a foundation rather than a completed social-network feature set; messaging, jobs and other proposed business capabilities are not presented here as verified completed features.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://bishnoi.pro/"}], "category": "Web & SaaS Applications", "featured": false, "features": ["Dedicated desktop/mobile design library", "Responsive public application foundation", "Account, session and role foundations", "Shared interface and domain packages", "Administrative and audit foundations"], "description": "A professional community product foundation with a dedicated design library, application shell and account infrastructure.", "technologies": ["Next.js", "React", "TypeScript", "Fastify", "PostgreSQL", "Drizzle"], "project_status": "Public website · product foundation", "evidence_attested": true, "challenges": [], "platforms": ["Web", "Mobile foundation"], "media_ids": []}'::jsonb,'{"title": "Bishnoi.pro — Professional Community Foundation | Anil Bishnoi", "description": "A professional community product foundation with a dedicated design library, application shell and account infrastructure.", "canonical": "https://anibish.com/portfolio/bishnoi-pro"}'::jsonb,'{"title": "Bishnoi.pro — Professional Community Foundation | Anil Bishnoi", "description": "A professional community product foundation with a dedicated design library, application shell and account infrastructure.", "canonical": "https://anibish.com/portfolio/bishnoi-pro"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
INSERT INTO cms_pages(slug,title,kind,state,content,published_content,seo,published_seo,published_at) VALUES('portfolio/carswhere','CarsWhere — Automotive Research & Discovery','portfolio','published','{"body": "CarsWhere brings new-car research, used-car discovery, dealership information and automotive editorial content into one web product. Its public experience includes car-finder and comparison areas alongside reviews, news, deals and community sections.\n\nThe engineering work is represented by a responsive web application, backend services and a React Native mobile codebase. Mobile implementation is documented; app-store availability and complete feature parity across platforms are not asserted.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://www.carswhere.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["New-car discovery and comparison areas", "Used-car listings and dealership discovery", "Automotive news, reviews and deals", "Community and account-related application areas", "Responsive web and documented mobile-client implementation"], "description": "An India-focused automotive platform combining car research, comparisons, listings, editorial content and community areas.", "technologies": ["Next.js", "TypeScript", "NestJS", "React Native", "Expo", "PostgreSQL"], "project_status": "Public website · web and mobile engineering", "evidence_attested": true, "challenges": [], "platforms": ["Web", "iOS/Android codebase"], "media_ids": []}'::jsonb,'{"body": "CarsWhere brings new-car research, used-car discovery, dealership information and automotive editorial content into one web product. Its public experience includes car-finder and comparison areas alongside reviews, news, deals and community sections.\n\nThe engineering work is represented by a responsive web application, backend services and a React Native mobile codebase. Mobile implementation is documented; app-store availability and complete feature parity across platforms are not asserted.", "mode": "enhance", "role": "Software engineering and product development · owner-approved portfolio project", "sources": [{"label": "Public product website", "url": "https://www.carswhere.com/"}], "category": "Web & SaaS Applications", "featured": true, "features": ["New-car discovery and comparison areas", "Used-car listings and dealership discovery", "Automotive news, reviews and deals", "Community and account-related application areas", "Responsive web and documented mobile-client implementation"], "description": "An India-focused automotive platform combining car research, comparisons, listings, editorial content and community areas.", "technologies": ["Next.js", "TypeScript", "NestJS", "React Native", "Expo", "PostgreSQL"], "project_status": "Public website · web and mobile engineering", "evidence_attested": true, "challenges": [], "platforms": ["Web", "iOS/Android codebase"], "media_ids": []}'::jsonb,'{"title": "CarsWhere — Automotive Research & Discovery | Anil Bishnoi", "description": "An India-focused automotive platform combining car research, comparisons, listings, editorial content and community areas.", "canonical": "https://anibish.com/portfolio/carswhere"}'::jsonb,'{"title": "CarsWhere — Automotive Research & Discovery | Anil Bishnoi", "description": "An India-focused automotive platform combining car research, comparisons, listings, editorial content and community areas.", "canonical": "https://anibish.com/portfolio/carswhere"}'::jsonb,now()) ON CONFLICT(slug) DO NOTHING;
